const timelineBucket = `-- name: TimelineBucket :many
SELECT a.id, a.user_id, a.kind, a.width, a.height, a.aspect_ratio, a.blurhash, a.is_favorite, a.local_at, a.duration_ms,
       EXISTS (SELECT 1 FROM assets v WHERE v.live_photo_of = a.id AND v.deleted_at IS NULL)::boolean AS is_live,
       (SELECT count(*) FROM assets m WHERE m.stack_parent = a.id)::bigint AS stack_members
FROM assets a
WHERE a.user_id = $1 AND a.status = 'ready' AND a.deleted_at IS NULL AND a.archived_at IS NULL AND a.vault_at IS NULL AND a.live_photo_of IS NULL AND a.stack_parent IS NULL
  AND a.local_at >= $2 AND a.local_at < $3
ORDER BY a.local_at DESC, a.id DESC
`

type TimelineBucketParams struct {
	UserID pgtype.UUID
	FromAt pgtype.Timestamp
	ToAt   pgtype.Timestamp
}

type TimelineBucketRow struct {
	ID           pgtype.UUID
	UserID       pgtype.UUID
	Kind         string
	Width        pgtype.Int4
	Height       pgtype.Int4
	AspectRatio  pgtype.Float4
	Blurhash     pgtype.Text
	IsFavorite   bool
	LocalAt      pgtype.Timestamp
	DurationMs   pgtype.Int8
	IsLive       bool
	StackMembers int64
}

func (q *Queries) TimelineBucket(ctx context.Context, arg TimelineBucketParams) ([]TimelineBucketRow, error) {
	rows, err := q.db.Query(ctx, timelineBucket, arg.UserID, arg.FromAt, arg.ToAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TimelineBucketRow
	for rows.Next() {
		var i TimelineBucketRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Kind,
			&i.Width,
			&i.Height,
			&i.AspectRatio,
			&i.Blurhash,
			&i.IsFavorite,
			&i.LocalAt,
			&i.DurationMs,
			&i.IsLive,
			&i.StackMembers,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const timelineBuckets = `-- name: TimelineBuckets :many
SELECT to_char(date_trunc('month', local_at), 'YYYY-MM')::text AS month, count(*) AS count
FROM assets
WHERE user_id = $1 AND status = 'ready' AND deleted_at IS NULL AND archived_at IS NULL AND vault_at IS NULL AND live_photo_of IS NULL AND stack_parent IS NULL
GROUP BY 1
ORDER BY 1 DESC
`

type TimelineBucketsRow struct {
	Month string
	Count int64
}

func (q *Queries) TimelineBuckets(ctx context.Context, userID pgtype.UUID) ([]TimelineBucketsRow, error) {
	rows, err := q.db.Query(ctx, timelineBuckets, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TimelineBucketsRow
	for rows.Next() {
		var i TimelineBucketsRow
		if err := rows.Scan(&i.Month, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

